import React, { useCallback } from "react";
import { Button, ButtonProps } from "@arco-design/web-react";
import { useFormStep } from "../hooks";
import { observer, useForm } from "@formily/react";

const NextButton = observer((props: ButtonProps) => {
  const formStep = useFormStep();
  const form = useForm();

  const onClick = useCallback((e) => {
    props?.onClick?.(e);
    formStep?.next();
  }, []);

  return (
    <Button
      disabled={!formStep?.allowNext || form?.submitting}
      loading={formStep?.nexting}
      {...props}
      onClick={onClick}
    >
      {props.children || "下一步"}
    </Button>
  );
});

export default Object.assign(NextButton, { __BYTE_BUTTON: true });
